select status, case when status in ('FAILED', 'SUCCESS') then 'priority' else 'other' end as status_group, count(amount) as amount_count, sum(case when status = 'FAILED' then amount else 0 end) as failed_amount from payments where order_id in (6, 32) and method in ('cash', 'paypal', 'bank_transfer') group by status, case when status in ('FAILED', 'SUCCESS') then 'priority' else 'other' end order by status
